; hidden_2.asm -- appendix B: bits 3 and 5 and MEMPTR, part 2 of 2
; generated by genB.py
        INCLUDE "msx.inc"
        OUTPUT "hidden_2.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM

; Every instruction but HALT and the RSTs, run from a table as Appendix
; A's flags.asm runs them: each with the eight Fs of fvals, from every state
; of its group. Each is first copied to buf, in the RAM, to end just where
; after begins, with base before it; a jump goes to away. measB.py stops at
; after and at away, with nothing run between the instruction and the
; stop, and reads every register; and again after the BIT 0,(HL) that
; follows, for bits 5 and 3 of MEMPTR's high byte, which BIT puts in F.
; This cartridge runs part 2 of 2 of the table.
WIN     equ $E1FC               ; the bytes read and written: (HL) is WIN+4
STK     equ $E210               ; SP for the runs
TOP     equ $F37E               ; SP between them
CARRY   equ $E7FF               ; an address + 1 that carries
S_BC    equ $B1C1               ; BC', DE' and HL' before each run
S_DE    equ $D1E1
S_HL    equ $4161
FVN     equ 8                   ; how many Fs
BUF     equ 16                  ; room for base and the longest block
AFTER   equ $C810               ; where after is, in the RAM
go      equ VARS                ; JP, and where the block begins
ip      equ VARS + 3            ; the instruction table, where it has got to
blk     equ VARS + 5            ; the block
gp      equ VARS + 7            ; the group's list of states
gn      equ VARS + 9            ; states left
sv      equ VARS + 10           ; the state
fi      equ VARS + 12           ; which F
spv     equ VARS + 13           ; SP
cur     equ VARS + 16           ; the state, copied: F goes into it
STATE   equ 27                  ; a state's bytes

init:   di
        ld sp,TOP
        VDP_REG 1, $80          ; display off, no signal from the VDP
        call quick              ; page 2: the cartridge's second half
        ld hl,$D000
        ld de,$D001
        ld bc,$1FFF
        ld (hl),0
        ldir                    ; the RAM the runs use, cleared
        ld hl,stub
        ld de,after
        ld bc,stub_end-stub
        ldir                    ; after and away, into the RAM
        ld a,$C3
        ld (go),a               ; JP
        ld a,0
        out (PSG_ADDR),a        ; the PSG's register 0, which $A2 reads
        ld hl,itab
        ld (ip),hl
inst:   ld hl,(ip)              ; the next instruction
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld a,d
        or e
        jp z,done               ; a 0: the table is done
        ld (blk),de             ; its block: the length, then the bytes
        ld e,(hl)               ; its group's number
        inc hl
        ld (ip),hl
        ld d,0
        ld hl,gtab
        add hl,de
        add hl,de
        ld e,(hl)
        inc hl
        ld d,(hl)
        ex de,hl                ; HL: its group
        ld a,(hl)
        ld (gn),a               ; how many states
        inc hl
        ld (gp),hl
state:  ld hl,(gp)              ; the next state
        ld e,(hl)
        inc hl
        ld d,(hl)
        inc hl
        ld (gp),hl
        ld (sv),de
        xor a
        ld (fi),a               ; the first F
run:    ld sp,TOP
        ld a,$3F
        ld i,a                  ; I, the same every run
        im 1
        ld hl,(blk)
        ld a,(hl)               ; the block's length
        add a,4                 ; and base's
        ld c,a
        ld a,low after
        sub c
        ld e,a
        ld a,high after
        sbc a,0
        ld d,a                  ; DE: after, less the two
        ld (go+1),de
        ld hl,base
        ld bc,4
        ldir                    ; base first
        ld hl,(blk)
        ld c,(hl)
        ld b,0
        inc hl
        ldir                    ; then the block, to end at after
        xor a
        ld (CARRY),a
        ld (CARRY+1),a          ; the bytes at CARRY: 0 before every run
        ld hl,(sv)
        ld de,cur
        ld bc,STATE
        ldir                    ; the state, into the RAM
        ld ix,cur
        ld a,(ix+18)
        out (PSG_WRITE),a       ; what port $A2 reads
        push ix
        pop hl
        ld de,19
        add hl,de
        ld de,WIN
        ld bc,8
        ldir                    ; the bytes at WIN
        ld l,(ix+14)
        ld h,(ix+15)
        ld (STK),hl             ; the word at STK
        ld l,(ix+12)
        ld h,(ix+13)
        ld (spv),hl             ; SP
        exx
        ld bc,S_BC
        ld de,S_DE
        ld hl,S_HL
        exx
        ld l,(ix+16)
        ld h,(ix+17)
        push hl
        pop af
        ex af,af'               ; AF'
        ld a,(fi)
        ld e,a
        ld d,0
        ld hl,fvals
        add hl,de
        ld a,(hl)
        ld (ix+0),a             ; F, into the state
        ld sp,ix
        pop af                  ; and the registers
        pop bc
        pop de
        pop hl
        pop ix
        pop iy
        ld sp,(spv)
        jp go                   ; base and the block: they end at after
save:   di
        ld sp,TOP
        ld a,(fi)
        inc a
        ld (fi),a
        cp FVN
        jp nz,run               ; the next F
        ld a,(gn)
        dec a
        ld (gn),a
        jp nz,state
        jp inst
done:   jr done

base:   ld ($1356),sp           ; before every block: MEMPTR $1357

; buf, after and away: in the RAM, where the blocks run
stub:   DISP AFTER
after:  bit 0,(hl)              ; MEMPTR's bits 5 and 3 into F
        jp save
away:   bit 0,(hl)              ; where the jumps go
        jp save
        ENT
stub_end:
buf     equ after-BUF

; quick: page 2 shows page 1's primary slot: port $A8 alone. Uses A, B, C
quick:  in a, (PPI_A)           ; 12
        ld b, a                 ;  5
        and %00001100           ;  8  page 1's primary slot
        add a, a                ;  5
        add a, a                ;  5  moved to page 2's bits
        ld c, a                 ;  5
        ld a, b                 ;  5
        and %11001111           ;  8
        or c                    ;  5
        out (PPI_A), a          ; 12  page 2 = this cartridge, too
        ret                     ; 11

fvals:  db $00,$FF,$01,$FE,$10,$11,$02,$03
                                ; the Fs, in turn

